#!/bin/bash\n\n# ============================================================================\n# AUDIOBOOK STUDIO - QUICK START SCRIPT\n# ============================================================================\n# This script sets up and starts all services\n# Usage: ./scripts/quickstart.sh [start|stop|restart|logs|status]\n# ============================================================================\n\nset -e\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Script directory\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_DIR=\"$(dirname \"$SCRIPT_DIR\")\"\n\n# ============================================================================\n# FUNCTIONS\n# ============================================================================\n\nprint_header() {\n    echo -e \"${BLUE}═══════════════════════════════════════════════════════════${NC}\"\n    echo -e \"${BLUE}$1${NC}\"\n    echo -e \"${BLUE}═══════════════════════════════════════════════════════════${NC}\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}✓ $1${NC}\"\n}\n\nprint_error() {\n    echo -e \"${RED}✗ $1${NC}\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}⚠ $1${NC}\"\n}\n\nprint_info() {\n    echo -e \"${BLUE}ℹ $1${NC}\"\n}\n\ncheck_docker() {\n    if ! command -v docker &> /dev/null; then\n        print_error \"Docker is not installed\"\n        print_info \"Install Docker from https://www.docker.com/products/docker-desktop\"\n        exit 1\n    fi\n    print_success \"Docker found: $(docker --version)\"\n}\n\ncheck_docker_compose() {\n    if ! command -v docker-compose &> /dev/null; then\n        print_error \"Docker Compose is not installed\"\n        print_info \"Install Docker Compose from https://docs.docker.com/compose/install/\"\n        exit 1\n    fi\n    print_success \"Docker Compose found: $(docker-compose --version)\"\n}\n\ncheck_env_file() {\n    if [ ! -f \"$PROJECT_DIR/.env\" ]; then\n        print_warning \".env file not found\"\n        print_info \"Creating .env from .env.example\"\n        cp \"$PROJECT_DIR/.env.example\" \"$PROJECT_DIR/.env\"\n        print_success \".env file created\"\n    fi\n}\n\nstart_services() {\n    print_header \"Starting Audiobook Studio Services\"\n    \n    cd \"$PROJECT_DIR\"\n    \n    print_info \"Building images...\"\n    docker-compose build --no-cache\n    \n    print_info \"Starting services...\"\n    docker-compose up -d\n    \n    print_info \"Waiting for services to be healthy...\"\n    sleep 10\n    \n    # Check service health\n    print_info \"Checking service health...\"\n    \n    if curl -s http://localhost:3000/health > /dev/null; then\n        print_success \"Backend API is healthy\"\n    else\n        print_warning \"Backend API is not responding yet\"\n    fi\n    \n    if curl -s http://localhost:5000/health > /dev/null; then\n        print_success \"TTS Engine is healthy\"\n    else\n        print_warning \"TTS Engine is not responding yet\"\n    fi\n    \n    print_header \"Services Started Successfully\"\n    print_info \"Frontend:  http://localhost:5173\"\n    print_info \"Backend:   http://localhost:3000\"\n    print_info \"TTS:       http://localhost:5000\"\n    print_info \"Redis:     localhost:6379\"\n    print_info \"\"\n    print_info \"View logs: docker-compose logs -f\"\n    print_info \"Stop services: docker-compose down\"\n}\n\nstop_services() {\n    print_header \"Stopping Services\"\n    cd \"$PROJECT_DIR\"\n    docker-compose down\n    print_success \"Services stopped\"\n}\n\nrestart_services() {\n    print_header \"Restarting Services\"\n    stop_services\n    sleep 2\n    start_services\n}\n\nshow_logs() {\n    print_header \"Viewing Logs\"\n    cd \"$PROJECT_DIR\"\n    docker-compose logs -f\n}\n\nshow_status() {\n    print_header \"Service Status\"\n    cd \"$PROJECT_DIR\"\n    docker-compose ps\n    \n    echo \"\"\n    print_info \"Health Check Results:\"\n    \n    if curl -s http://localhost:3000/health > /dev/null; then\n        print_success \"Backend API: Healthy\"\n    else\n        print_error \"Backend API: Not responding\"\n    fi\n    \n    if curl -s http://localhost:5000/health > /dev/null; then\n        print_success \"TTS Engine: Healthy\"\n    else\n        print_error \"TTS Engine: Not responding\"\n    fi\n    \n    if curl -s http://localhost:5173 > /dev/null 2>&1; then\n        print_success \"Frontend: Healthy\"\n    else\n        print_error \"Frontend: Not responding\"\n    fi\n}\n\nshow_help() {\n    echo \"\"\n    print_header \"Audiobook Studio - Quick Start\"\n    echo \"\"\n    echo \"Usage: $0 [COMMAND]\"\n    echo \"\"\n    echo \"Commands:\"\n    echo \"  start       Start all services (default)\"\n    echo \"  stop        Stop all services\"\n    echo \"  restart     Restart all services\"\n    echo \"  logs        View service logs\"\n    echo \"  status      Show service status\"\n    echo \"  help        Show this help message\"\n    echo \"\"\n    echo \"Examples:\"\n    echo \"  $0 start\"\n    echo \"  $0 logs\"\n    echo \"  $0 status\"\n    echo \"\"\n}\n\n# ============================================================================\n# MAIN\n# ============================================================================\n\nmain() {\n    # Check prerequisites\n    check_docker\n    check_docker_compose\n    check_env_file\n    \n    # Get command\n    COMMAND=\"${1:-start}\"\n    \n    case \"$COMMAND\" in\n        start)\n            start_services\n            ;;\n        stop)\n            stop_services\n            ;;\n        restart)\n            restart_services\n            ;;\n        logs)\n            show_logs\n            ;;\n        status)\n            show_status\n            ;;\n        help|--help|-h)\n            show_help\n            ;;\n        *)\n            print_error \"Unknown command: $COMMAND\"\n            show_help\n            exit 1\n            ;;\n    esac\n}\n\n# Run main function\nmain \"$@\"\n
